class Solution:
    def getRow(self, rowIndex: int) -> List[int]:
        row = [1]
        for _ in range(rowIndex):
            row.append(1)
            for j in range(len(row) - 2, 0, -1):
                row[j] += row[j - 1]
        return row

code.C:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int* getRow(int rowIndex, int* returnSize) {
    int n = rowIndex + 1;
    int* row = (int*)malloc((size_t)n * sizeof(int));
    if (!row) {
        *returnSize = 0;
        return NULL;
    }
    row[0] = 1;
    for (int i = 1; i < n; ++i) {
        row[i] = 1;
        for (int j = i - 1; j > 0; --j) {
            row[j] += row[j - 1];
        }
    }
    *returnSize = n;
    return row;
}

